export const LOGIN_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>myDav · 夸克网盘 WebDAV</title>\n  <style>\n    :root { --bg:#f5f8ff; --card:#fff; --primary:#3b82f6; --text:#1f2937; --muted:#6b7280; }\n    * { box-sizing: border-box; }\n    body { margin:0; font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;\n      background:linear-gradient(160deg,#eef4ff,#f7faff); color:var(--text); min-height:100vh; padding:24px; }\n    .wrap { max-width:760px; margin:0 auto; }\n    .card { background:var(--card); border-radius:18px; padding:28px; box-shadow:0 10px 40px rgba(59,130,246,.12); }\n    h1 { font-size:20px; margin:0 0 4px; }\n    .sub { color:var(--muted); font-size:13px; margin-bottom:20px; }\n    .center { text-align:center; }\n    .qr { width:220px; height:220px; margin:0 auto 16px; border-radius:12px; background:#f1f5f9;\n      display:flex; align-items:center; justify-content:center; overflow:hidden; }\n    .qr img { width:100%; height:100%; object-fit:contain; }\n    .qr .ph { color:var(--muted); font-size:13px; }\n    .status { font-size:14px; margin-bottom:16px; min-height:20px; }\n    .ok { color:#16a34a; } .wait { color:var(--muted); }\n    button { padding:10px 16px; border:none; border-radius:10px; background:var(--primary);\n      color:#fff; font-size:14px; cursor:pointer; transition:.15s; }\n    button:hover { background:#2563eb; }\n    button.ghost { background:#eef2ff; color:var(--primary); }\n    button.danger { background:#fee2e2; color:#dc2626; }\n    button:disabled { opacity:.6; cursor:not-allowed; }\n    input { width:100%; padding:11px 14px; border:1px solid #dbe4f5; border-radius:10px;\n      font-size:14px; outline:none; transition:.15s; }\n    input:focus { border-color:var(--primary); box-shadow:0 0 0 3px rgba(59,130,246,.12); }\n    .field { margin-bottom:12px; }\n    .hint { font-size:12px; color:var(--muted); margin-top:16px; line-height:1.7; }\n    code { background:#eef2ff; padding:1px 6px; border-radius:6px; font-size:12px; word-break:break-all; }\n    .box { background:#f8fafc; border:1px solid #e8eefc; border-radius:12px; padding:14px; margin:14px 0; font-size:13px; line-height:1.7; }\n    .box b { color:var(--primary); }\n    .row { display:flex; gap:8px; align-items:center; flex-wrap:wrap; }\n    .breadcrumb { font-size:13px; color:var(--muted); margin-bottom:10px; }\n    .breadcrumb a { color:var(--primary); cursor:pointer; text-decoration:none; }\n    .files { list-style:none; margin:0; padding:0; }\n    .files li { display:flex; align-items:center; gap:10px; padding:10px 12px; border-radius:10px; }\n    .files li:hover { background:#f1f5f9; }\n    .files .ico { width:22px; text-align:center; }\n    .files .name { flex:1; cursor:pointer; word-break:break-all; }\n    .files .name.folder { color:var(--primary); font-weight:600; }\n    .files .meta { color:var(--muted); font-size:12px; }\n    .files a.open { color:var(--primary); font-size:12px; text-decoration:none; }\n    .err { color:#dc2626; font-size:13px; margin-bottom:10px; min-height:18px; }\n    .tip { color:var(--muted); font-size:12px; }\n    .tip.done { color:#16a34a; }\n    [hidden] { display:none !important; }\n  </style>\n</head>\n<body>\n  <div class=\"wrap\">\n    <!-- 管理员验证视图 -->\n    <div class=\"card\" id=\"adminView\">\n      <h1>🔒 myDav 管理台</h1>\n      <div class=\"sub\" id=\"adminSub\">请输入管理员密码</div>\n      <div class=\"err\" id=\"adminErr\"></div>\n      <div class=\"field\"><input type=\"password\" id=\"adminPw\" placeholder=\"管理员密码\" autocomplete=\"current-password\" /></div>\n      <div class=\"field\" id=\"adminPw2Wrap\" hidden>\n        <input type=\"password\" id=\"adminPw2\" placeholder=\"再输入一次\" autocomplete=\"new-password\" />\n      </div>\n      <div class=\"row\"><button id=\"adminBtn\">进入</button></div>\n      <div class=\"hint\" id=\"adminHint\">\n        密码用于保护本管理台、所有接口与 WebDAV 挂载地址。<br/>\n        忘记密码只能重设：删除服务端 <code>data/admin.json</code> 后重新设置。\n      </div>\n    </div>\n\n    <!-- 夸克扫码登录视图 -->\n    <div class=\"card\" id=\"loginView\" hidden>\n      <h1>myDav</h1>\n      <div class=\"sub\">夸克网盘 → WebDAV 桥接 · 用夸克 App 扫码登录</div>\n      <div class=\"center\">\n        <div class=\"qr\" id=\"qr\"><div class=\"ph\">点击下方按钮获取二维码</div></div>\n        <div class=\"status wait\" id=\"status\">未登录</div>\n        <button id=\"start\">获取登录二维码</button>\n      </div>\n    </div>\n\n    <!-- 仪表盘视图 -->\n    <div class=\"card\" id=\"dashView\" hidden>\n      <div class=\"row\" style=\"justify-content:space-between;\">\n        <div><h1>✅ 已登录</h1><div class=\"sub\">夸克网盘文件 · 可直接在网页浏览</div></div>\n        <button class=\"ghost\" id=\"logout\">退出夸克登录</button>\n      </div>\n\n      <div class=\"box\">\n        <div style=\"margin-bottom:6px;\"><b>挂载信息</b></div>\n        主机：<code id=\"host\"></code><br/>\n        路径：<code id=\"davPath\"></code><br/>\n        账号：<code>admin</code> · 密码：<code>admin</code>（线上由路径里的密钥鉴权，此两栏任意填）<br/>\n        <div class=\"row\" style=\"margin-top:10px;\">\n          <button id=\"copyMount\">一键复制挂载信息</button>\n          <span class=\"tip\" id=\"copyTip\">复制后直接粘贴到播放器</span>\n        </div>\n      </div>\n\n      <div class=\"box\">\n        <div style=\"margin-bottom:6px;\"><b>挂载密钥</b>（路径里的 <code>/dav/<span id=\"curSecret\"></span></code>）</div>\n        <div class=\"row\">\n          <input id=\"secretInput\" style=\"flex:1;min-width:180px;\" placeholder=\"输入自定义密钥（至少 6 位，勿含空格或斜杠）\" />\n          <button id=\"saveSecret\">保存</button>\n          <button class=\"ghost\" id=\"randSecret\">随机生成</button>\n        </div>\n        <div class=\"hint\" style=\"margin-top:8px;\">\n          改密钥后旧挂载地址立即失效，播放器需用新地址重新添加。建议用你自己的易记口令。\n        </div>\n      </div>\n\n      <div class=\"breadcrumb\" id=\"crumb\"></div>\n      <ul class=\"files\" id=\"files\"></ul>\n      <div class=\"err\" id=\"ferr\"></div>\n    </div>\n  </div>\n\n  <script>\n    const startBtn = document.getElementById('start');\n    const statusEl = document.getElementById('status');\n    const qrEl = document.getElementById('qr');\n    const adminView = document.getElementById('adminView');\n    const loginView = document.getElementById('loginView');\n    const dashView = document.getElementById('dashView');\n    let timer = null, qt = null, davToken = '', curPath = '/', isSetup = false;\n\n    let adminToken = localStorage.getItem('myDavAdmin') || '';\n\n    const esc = (s) => String(s).replace(/[&<>\"']/g,\n      (c) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;' }[c]));\n    const enc = (s) => encodeURIComponent(s);\n\n    // Every authenticated call carries the admin session in a custom header —\n    // the hosting proxy strips Authorization, but custom headers pass through.\n    async function api(u, o = {}) {\n      const headers = Object.assign({}, o.headers || {});\n      if (adminToken) headers['X-Admin-Token'] = adminToken;\n      const r = await fetch(u, Object.assign({}, o, { headers }));\n      const d = await r.json().catch(() => ({}));\n      if (d.needAdmin) { adminToken = ''; localStorage.removeItem('myDavAdmin'); showAdmin(); throw new Error('会话已过期'); }\n      return d;\n    }\n\n    function showAdmin() {\n      adminView.hidden = false; loginView.hidden = true; dashView.hidden = true;\n    }\n    function setAdminToken(t) {\n      adminToken = t;\n      localStorage.setItem('myDavAdmin', t);\n    }\n\n    async function submitAdmin() {\n      const pw = document.getElementById('adminPw').value;\n      const errEl = document.getElementById('adminErr');\n      errEl.textContent = '';\n      if (!pw) { errEl.textContent = '请输入密码'; return; }\n      if (isSetup) {\n        const pw2 = document.getElementById('adminPw2').value;\n        if (pw !== pw2) { errEl.textContent = '两次输入的密码不一致'; return; }\n        if (pw.length < 8) { errEl.textContent = '密码至少 8 位'; return; }\n        const d = await fetch('/api/admin/setup', {\n          method: 'POST', headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ password: pw }),\n        }).then((r) => r.json());\n        if (d.error) { errEl.textContent = d.error; return; }\n        setAdminToken(d.token);\n      } else {\n        const d = await fetch('/api/admin/login', {\n          method: 'POST', headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ password: pw }),\n        }).then((r) => r.json());\n        if (d.error) { errEl.textContent = d.error; return; }\n        setAdminToken(d.token);\n      }\n      document.getElementById('adminPw').value = '';\n      document.getElementById('adminPw2').value = '';\n      await enterApp();\n    }\n\n    async function enterApp() {\n      adminView.hidden = true;\n      let s;\n      try { s = await api('/api/status'); } catch { return; }\n      davToken = s.webdavToken || davToken;\n      if (s.loggedIn) { await showDashboard(); return; }\n      // Not logged in on this worker (e.g. right after a redeploy).\n      const b = localStorage.getItem('myDavBackup');\n      if (b) {\n        try {\n          const r = await api('/api/restore', {\n            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: b,\n          });\n          if (r.loggedIn) { await showDashboard(); return; }\n        } catch {}\n      }\n      loginView.hidden = false;\n    }\n\n    function davUrl(path) {\n      const segs = path.split('/').filter(Boolean).map(enc).join('/');\n      return location.origin + '/dav/' + davToken + (segs ? '/' + segs : '');\n    }\n\n    async function showDashboard() {\n      loginView.hidden = true;\n      dashView.hidden = false;\n      document.getElementById('host').textContent = location.host;\n      document.getElementById('davPath').textContent = '/dav/' + davToken;\n      document.getElementById('curSecret').textContent = davToken;\n      document.getElementById('secretInput').value = '';\n      document.getElementById('copyMount').onclick = copyMountInfo;\n      await loadFiles(curPath || '/');\n    }\n\n    // Plain-text mount info, ready to paste into any WebDAV client.\n    function mountInfoText() {\n      return [\n        '地址：' + location.origin + '/dav/' + davToken,\n        '主机：' + location.host,\n        '路径：/dav/' + davToken,\n        '端口：443',\n        '协议：https',\n        '账号：admin',\n        '密码：admin',\n      ].join('\\n');\n    }\n\n    async function copyMountInfo() {\n      const text = mountInfoText();\n      const tip = document.getElementById('copyTip');\n      let done = false;\n      // navigator.clipboard needs a secure context and permission; fall back to\n      // a temporary textarea for http:// or older browsers.\n      try {\n        if (navigator.clipboard && window.isSecureContext) {\n          await navigator.clipboard.writeText(text);\n          done = true;\n        }\n      } catch {}\n      if (!done) {\n        try {\n          const ta = document.createElement('textarea');\n          ta.value = text;\n          ta.style.position = 'fixed';\n          ta.style.opacity = '0';\n          document.body.appendChild(ta);\n          ta.select();\n          done = document.execCommand('copy');\n          document.body.removeChild(ta);\n        } catch {}\n      }\n      if (done) {\n        tip.textContent = '✅ 已复制到剪贴板';\n        tip.className = 'tip done';\n        setTimeout(() => { tip.textContent = '复制后直接粘贴到播放器'; tip.className = 'tip'; }, 2200);\n      } else {\n        // Last resort: show it so it can be selected manually.\n        window.prompt('自动复制失败，请手动复制：', text);\n      }\n    }\n\n    async function loadFiles(path) {\n      curPath = path;\n      document.getElementById('ferr').textContent = '';\n      const crumb = document.getElementById('crumb');\n      crumb.innerHTML = '';\n      const parts = path.split('/').filter(Boolean);\n      let acc = '';\n      const addCrumb = (label, p) => {\n        const a = document.createElement('a');\n        a.textContent = label;              // textContent: filenames are untrusted\n        a.onclick = () => loadFiles(p);\n        crumb.appendChild(a);\n        crumb.appendChild(document.createTextNode(' / '));\n      };\n      addCrumb('根目录', '/');\n      for (const p of parts) { acc += '/' + p; addCrumb(p, acc); }\n\n      try {\n        const d = await api('/api/files?path=' + enc(path));\n        if (d.error) { document.getElementById('ferr').textContent = '⚠️ ' + d.error; return; }\n        const ul = document.getElementById('files');\n        ul.innerHTML = '';\n        const dirs = d.items.filter((i) => i.isdir).sort((a, b) => a.name.localeCompare(b.name, 'zh'));\n        const files = d.items.filter((i) => !i.isdir).sort((a, b) => a.name.localeCompare(b.name, 'zh'));\n        const fmt = (n) => (n > 1048576 ? (n / 1048576).toFixed(1) + 'MB' : (n / 1024).toFixed(0) + 'KB');\n        for (const it of [...dirs, ...files]) {\n          const li = document.createElement('li');\n          const full = (path === '/' ? '' : path) + '/' + it.name;\n          const ico = document.createElement('span');\n          ico.className = 'ico'; ico.textContent = it.isdir ? '📁' : '🎬';\n          const nm = document.createElement('span');\n          nm.className = 'name' + (it.isdir ? ' folder' : '');\n          nm.textContent = it.name;         // never innerHTML for untrusted names\n          if (it.isdir) nm.onclick = () => loadFiles(full);\n          li.appendChild(ico); li.appendChild(nm);\n          if (!it.isdir) {\n            const meta = document.createElement('span');\n            meta.className = 'meta'; meta.textContent = fmt(it.size || 0);\n            const open = document.createElement('a');\n            open.className = 'open'; open.href = davUrl(full);\n            open.target = '_blank'; open.textContent = '打开/播放';\n            li.appendChild(meta); li.appendChild(open);\n          }\n          ul.appendChild(li);\n        }\n      } catch (e) {\n        document.getElementById('ferr').textContent = '⚠️ 加载失败：' + e.message;\n      }\n    }\n\n    async function startLogin() {\n      startBtn.disabled = true;\n      statusEl.textContent = '正在生成二维码…'; statusEl.className = 'status wait';\n      try {\n        const d = await api('/api/login/start', { method: 'POST' });\n        if (!d.qr) throw new Error('服务端未返回二维码');\n        qrEl.innerHTML = `<img src=\"${esc(d.qr)}\" alt=\"qr\" />`;\n        qt = d.queryToken || null;\n        statusEl.textContent = '请用夸克 App 扫码并在手机上确认…';\n        poll();\n      } catch (e) {\n        startBtn.disabled = false;\n        statusEl.textContent = '⚠️ 获取失败：' + e.message;\n      }\n    }\n\n    function poll() {\n      if (timer) clearInterval(timer);\n      timer = setInterval(async () => {\n        try {\n          const d = await api('/api/login/status', {\n            method: 'POST', headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify({ queryToken: qt }),\n          });\n          if (d.loggedIn) {\n            clearInterval(timer);\n            try {\n              const s = await api('/api/status');\n              davToken = s.webdavToken || davToken;\n            } catch {}\n            await showDashboard();\n            await backupToLocal();\n            return;\n          }\n          if (d.error) {\n            const pending = /未确认|未扫码|等待|wait|pending|scan|无效|过期/i.test(d.error);\n            statusEl.textContent = pending ? '等待夸克 App 扫码并在手机上确认…'\n              : '⚠️ 登录异常：' + d.error + '（可刷新页面重试）';\n            statusEl.className = 'status wait';\n          }\n        } catch (e) {\n          statusEl.textContent = '检测登录中…（' + e.message + '）';\n        }\n      }, 2000);\n    }\n\n    async function backupToLocal() {\n      try {\n        const st = await api('/api/backup');\n        if (st && st.accessToken) localStorage.setItem('myDavBackup', JSON.stringify(st));\n      } catch {}\n    }\n\n    // Change the mount secret: body.secret = typed value, or empty for random.\n    async function changeSecret(secret) {\n      const d = await api('/api/webdav/rotate', {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ secret: secret || '' }),\n      });\n      if (d.error) throw new Error(d.error);\n      davToken = String(d.mountBase || '').replace('/dav/', '') || davToken;\n      await showDashboard();\n      if (d.unchanged) alert('密钥未变化（与当前相同）。');\n      else alert('✅ 密钥已更新为：' + davToken + '\\n请用新地址重新添加播放器。');\n    }\n\n    async function saveSecret() {\n      const v = document.getElementById('secretInput').value.trim();\n      if (!v) { alert('请输入密钥，或点「随机生成」。'); return; }\n      if (v.length < 6) { alert('密钥至少 6 位。'); return; }\n      if (/[/\\\\?#\\s]/.test(v)) { alert('密钥不能包含空格、斜杠或 ? # 字符。'); return; }\n      if (v === davToken) { alert('新密钥与当前密钥相同，无需修改。'); return; }\n      if (!confirm('将挂载密钥改为「' + v + '」？\\n旧地址会立即失效，播放器需重新添加。')) return;\n      try { await changeSecret(v); } catch (e) { alert('修改失败：' + e.message); }\n    }\n\n    async function randomSecret() {\n      if (!confirm('随机生成新密钥？旧地址会立即失效，播放器需重新添加。')) return;\n      try { await changeSecret(''); } catch (e) { alert('生成失败：' + e.message); }\n    }\n\n    async function logout() {\n      if (timer) clearInterval(timer);\n      localStorage.removeItem('myDavBackup');\n      try { await api('/api/logout', { method: 'POST' }); } catch {}\n      location.reload();\n    }\n\n    document.getElementById('adminBtn').onclick = submitAdmin;\n    document.getElementById('adminPw').addEventListener('keydown', (e) => { if (e.key === 'Enter') submitAdmin(); });\n    document.getElementById('adminPw2').addEventListener('keydown', (e) => { if (e.key === 'Enter') submitAdmin(); });\n    startBtn.onclick = startLogin;\n    document.getElementById('logout').onclick = logout;\n    document.getElementById('saveSecret').onclick = saveSecret;\n    document.getElementById('randSecret').onclick = randomSecret;\n    document.getElementById('secretInput').addEventListener('keydown', (e) => { if (e.key === 'Enter') saveSecret(); });\n\n    (async () => {\n      // First find out whether an admin password exists yet.\n      const st = await fetch('/api/admin/state').then((r) => r.json()).catch(() => ({}));\n      isSetup = !st.initialized;\n      if (isSetup) {\n        document.getElementById('adminSub').textContent = '首次使用：请设置管理员密码（至少 8 位）';\n        document.getElementById('adminPw').placeholder = '设置管理员密码';\n        document.getElementById('adminPw2Wrap').hidden = false;\n        document.getElementById('adminBtn').textContent = '设置密码并进入';\n      }\n      showAdmin();\n      if (!isSetup && adminToken) {\n        // We have a saved session — try to use it silently.\n        try { await enterApp(); } catch {}\n      }\n    })();\n  </script>\n</body>\n</html>\n";
